mapper.select:
SELECT fa.financial_account_id AS accountId, fa.owner_type AS ownerType, fa.owner_member_id AS ownerMemberId, fa.child_id AS childId, fa.bank_name AS bankName, fa.account_name AS accountName, fa.account_product_type AS accountProductType, fa.balance, fa.account_status AS accountStatus, fa.link_status AS linkStatus, fga.financial_goal_id AS financialGoalId FROM financial_account fa LEFT JOIN financial_goal_account fga ON fga.financial_account_id = fa.financial_account_id WHERE fa.financial_account_id IN
#{accountId}
FOR UPDATE

mapper.delete:
DELETE FROM financial_goal_account
WHERE financial_goal_id = #{financialGoalId}
  AND financial_account_id = #{financialAccountId}

mapper.update:
UPDATE financial_goal_checkpoint
SET target_amount = #{targetAmount},
    reached_at = #{reachedAt}
WHERE financial_goal_checkpoint_id = #{financialGoalCheckpointId}
